              const std::vector<int>& buf, int lo, int hi)
{
    const std::vector<ScampPrefix>& P = *c.p;
    int idx = (int)c.nodes.size();
    c.nodes.emplace_back();
    ExpNode& n = c.nodes[idx];
    n.origin = origin; n.depth = depth; n.level = (depth - origin)/6; n.region = region; n.key = key;
    int count = hi - lo;
    if (count <= 0) throw ...;  // never
    if (count <= 2) {
        n.type = (count==1) ? TYPE4 : TYPE5;
        n.ninl = count;
        n.owned = count;
        for (int i=0;i<count;++i) n.inl[i] = P[buf[lo+i]];
        return idx;
    }
    int limit = depth + 6;
    int max = scamp_origin_max(origin);
    std::vector<int> rest; rest.reserve(count);
    std::vector<std::pair<uint8_t,uint32_t>> locals; locals.reserve(count);
    for (int i=lo;i<hi;++i) {
        const ScampPrefix& pf = P[buf[i]];
        if ((int)pf.len < limit) {
            int l = (int)pf.len - depth;
            uint32_t v = scamp_bits(pf.addr, depth, l);
            uint8_t pos = (uint8_t)((1u<<l) + v);
            locals.emplace_back(pos, pf.hop);
        } else rest.push_back(buf[i]);
    }
    std::sort(locals.begin(), locals.end());
    for (auto& x : locals) { n.lpos.push_back(x.first); n.lhop.push_back(x.second); n.pattern |= (1ULL<<x.first); }
    /* children */
    int cnt[64] = {0};
    for (int id : rest) cnt[scamp_bits(P[id].addr, depth, 6)]++;
    std::vector<int> sorted(rest.size());
    {
        int start[65]; start[0]=0; for(k) start[k+1]=start[k]+cnt[k];
        int cur[64]; copy start;
        for (int id : rest) { int k = ...; sorted[cur[k]++] = id; }
    }
    for (int k=0;k<64;++k) if (cnt[k]) {
        u128_t cregion = region | (static_cast<u128_t>(k) << (128 - limit));
        int ci = exp_build(c, origin, key, cregion, limit, sorted, start[k], start[k+1]);
        n.ckey.push_back((uint8_t)k); n.cidx.push_back(ci);
    }
    int cc = (int)n.ckey.size();
    n.type = (cc<=2)?TYPE1:((cc<=6)?TYPE2:TYPE3);
    n.owned = (uint32_t)n.lpos.size();
    for (int ci : n.cidx) n.owned += c.nodes[ci].owned;
    return idx;
}
