#include "image_pack.h"
#include <cerrno>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>
#include <unistd.h>

/* Fast reader for the internal text wire produced by the fixed front end.
   The whole request is buffered once; tokens are whitespace separated. */
class WireInput {
public:
    WireInput() {
        size_t cap = 1u << 16, total = 0;
        buf_.resize(cap);
        for (;;) {
            if (total == buf_.size()) buf_.resize(buf_.size() * 2);
            ssize_t r = ::read(0, buf_.data() + total, buf_.size() - total);
            if (r < 0) {
                if (errno == EINTR) continue;
                throw std::runtime_error("wire read");
            }
            if (r == 0) break;
            total += static_cast<size_t>(r);
        }
        buf_.resize(total);
    }

    bool token(const char*& start, size_t& len) {
        while (pos_ < buf_.size() && static_cast<unsigned char>(buf_[pos_]) <= 32u) ++pos_;
        if (pos_ >= buf_.size()) return false;
        size_t s = pos_;
        while (pos_ < buf_.size() && static_cast<unsigned char>(buf_[pos_]) > 32u) ++pos_;
        start = buf_.data() + s;
        len = pos_ - s;
        return true;
    }

    void expect_token(const char*& start, size_t& len) {
        if (!token(start, len)) throw std::runtime_error("wire exhausted");
    }

    char op() {
        const char* s; size_t n;
        expect_token(s, n);
        if (n != 1) throw std::runtime_error("wire opcode");
        return s[0];
    }

    long long integer() {
        const char* s; size_t n;
        expect_token(s, n);
        size_t i = 0;
        bool neg = false;
        if (i < n && s[i] == '-') { neg = true; ++i; }
        if (i >= n) throw std::runtime_error("wire integer");
        long long v = 0;
        for (; i < n; ++i) {
            if (s[i] < '0' || s[i] > '9') throw std::runtime_error("wire integer");
            v = v * 10 + (s[i] - '0');
            if (v > 4000000000LL) throw std::runtime_error("wire integer range");
        }
        return neg ? -v : v;
    }

    unsigned uinteger() {
        long long v = integer();
        if (v < 0) throw std::runtime_error("wire unsigned");
        return static_cast<unsigned>(v);
    }

    static int nibble(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        return -1;
    }

    /* exactly `digits` lowercase hex characters, most significant first */
    uint64_t hex_fixed(int digits) {
        const char* s; size_t n;
        expect_token(s, n);
        if (static_cast<int>(n) != digits || digits > 16) throw std::runtime_error("wire hex");
        uint64_t v = 0;
        for (int i = 0; i < digits; ++i) {
            int d = nibble(s[i]);
            if (d < 0) throw std::runtime_error("wire hex");
            v = (v << 4) | static_cast<uint64_t>(d);
        }
        return v;
    }

    Row256 word() {
        const char* s; size_t n;
        expect_token(s, n);
        if (n != 64) throw std::runtime_error("wire word");
        Row256 out;
        for (int i = 0; i < 64; ++i) {
            int d = nibble(s[63 - i]);
            if (d < 0) throw std::runtime_error("wire word");
            for (int b = 0; b < 4; ++b) out[4 * i + b] = ((d >> b) & 1) != 0;
        }
        return out;
    }

    bool at_end() {
        const char* s; size_t n;
        size_t save = pos_;
        bool have = token(s, n);
        pos_ = save;
        return !have;
    }

private:
    std::vector<char> buf_;
    size_t pos_ = 0;
};

#endif /* SCAMP_WIRE_IO_HPP */
